  23	fn map_reason_to_change_source(
  24	    reason: &BumpReason,
  25	    id: &callisto_model::PackageId,
  26	    to: &callisto_model::Version,
  27	    outcome: &crate::cascade::CascadeOutcome,
  28	    agg: &crate::aggregate::Aggregation,
  29	) -> Option<ChangeSource> {
  30	    match reason {
  31	        BumpReason::FixedGroupUnion { group } => Some(ChangeSource::GroupUnion {
  32	            group: group.clone(),
  33	            kind: GroupKind::Fixed,
  34	        }),
  35	        BumpReason::LinkedGroupUnion { group } => Some(ChangeSource::GroupUnion {
  36	            group: group.clone(),
  37	            kind: GroupKind::Linked,
  38	        }),
  39	        BumpReason::Cascade {
  40	            via,
  41	            dep_kind,
  42	            dependency_to,
  43	            ..
  44	        } => Some(ChangeSource::DependencyUpdate {
  45	            dependency: via.clone(),
  46	            dep_kind: *dep_kind,
  47	            to: dependency_to.clone(),
  48	        }),
  49	        BumpReason::PeerEscalation { via, .. } => {
  50	            let dep_to = outcome.targets.get(via).cloned().unwrap_or_else(|| to.clone());
  51	            Some(ChangeSource::PeerEscalation {
  52	                dependency: via.clone(),
  53	                to: dep_to,
  54	            })
  55	        }
  56	        BumpReason::Inference { commits, .. } => match agg.inference_commits.get(id).and_then(|c| c.first()) {
  57	            Some((sha, subject)) => Some(ChangeSource::Commit {
  58	                sha: sha.clone(),
  59	                subject: subject.clone(),
  60	            }),
  61	            None => Some(ChangeSource::Changeset {
  62	                filename: String::new(),
  63	                summary: format!("Inferred version bump ({commits} commit(s))"),
  64	            }),
  65	        },
  66	        _ => None,
  67	    }
  68	}
