  70	pub fn plan_version<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
  71	    ws: &Workspace<'_, R, D>,
  72	    inference: &I,
  73	    opts: &VersionOptions,
  74	) -> Result<VersionPlan, GraphError> {
  75	    let base_versions = ws.base_versions()?;
  76	    let tags = ws.tags()?;
  77	
  78	    let pre_path = ws.root.join(ws.config.pre_json_path());
  79	    let (pre_state, pre_json_original_text) = if pre_path.exists() {
  80	        let text =
  81	            std::fs::read_to_string(&pre_path).map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
  82	        let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
  83	        let state = ws.resolve_pre_state_from_json(state, &text)?;
  84	        (Some(state), Some(text))
  85	    } else {
  86	        (None, None)
  87	    };
  88	
  89	    let mut agg = aggregate(
  90	        &ws.graph,
  91	        &ws.identity,
  92	        &ws.config,
  93	        ws.git_access(),
  94	        tags,
  95	        &base_versions,
  96	        pre_state.as_ref(),
  97	        inference,
  98	    )?;
  99	
 100	    // For PreMode::Exit, inject a synthetic Patch severity for every package
 101	    // that is currently at a pre-release version. This triggers bump_target
 102	    // (which in Exit mode calls versioning.bump on the pre-release, stripping
 103	    // the tag and finalizing to stable) even when no pending changeset files
 104	    // exist on disk — they were consumed and deleted during the pre-release phase
 105	    // and their stems recorded in pre.json.
 106	    if let Some(ref pre) = pre_state {
 107	        if pre.mode == callisto_model::format::PreMode::Exit {
 108	            for (id, ver) in &base_versions {
 109	                if ver.is_prerelease() {
 110	                    agg.severities.entry(id.clone()).or_insert(Severity::Patch);
 111	                    agg.reasons
 112	                        .entry(id.clone())
 113	                        .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
 114	                }
 115	            }
 116	        }
 117	    }
 118	
 119	    let input = CascadeInput {
 120	        graph: &ws.graph,
 121	        groups: &ws.config.groups,
 122	        cfg: &ws.config.cascade,
 123	        seed: &agg.severities,
 124	        reasons: &agg.reasons,
 125	        named_by: &agg.named_by,
 126	        base: &base_versions,
 127	        pre: pre_state.as_ref(),
 128	        tags,
 129	        identity: &ws.identity,
 130	    };
 131	
 132	    let napi = crate::napi::NapiTargetsIndex::load(&ws.config.groups, &ws.root)?;
 133	    let group_check =
 134	        crate::groups::pre_mutation_checks(&ws.graph, &ws.config.groups, &base_versions, tags, &napi, &ws.root)?;
 135	
 136	    let outcome = run_cascade(input)?;
 137	
 138	    let mut bumps = Vec::new();
 139	    let mut changelog_writes = Vec::new();
 140	
 141	    // PERF-006: build a map once so each lookup inside the loop is O(1)
 142	    // instead of O(N) (the previous packages().find() call).
 143	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
 144	
 145	    for (id, &sev) in &outcome.severities {
 146	        if sev == Severity::None {
 147	            continue;
 148	        }
 149	        let pkg = pkg_map.get(id).copied().unwrap();
 150	        let from = base_versions.get(id).cloned().ok_or_else(|| {
 151	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
 152	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
 153	                field: "version",
 154	            })
 155	        })?;
 156	        let to = outcome.targets.get(id).cloned().ok_or_else(|| {
 157	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
 158	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
 159	                field: "version",
 160	            })
 161	        })?;
 162	
 163	        let mut writes = Vec::new();
 164	        for decl in &pkg.manifests {
 165	            if decl.role == callisto_model::ManifestRole::Canonical {
 166	                writes.push(VersionWriteTarget::Manifest(decl.path.clone()));
 167	            }
 168	        }
 169	
 170	        bumps.push(PlannedBump {
 171	            package: id.clone(),
 172	            from: from.clone(),
 173	            to: to.clone(),
 174	            severity: sev,
 175	            governed_by: outcome.governed_by.get(id).cloned(),
 176	            reason: outcome.reasons.get(id).cloned(),
 177	            writes,
 178	        });
 179	
 180	        if let Some(ch_path) = &pkg.changelog {
 181	            let mut input = if let Some(mut agg_input) = agg.changelog_inputs.get(id).cloned() {
 182	                // Real changeset data: use it, but set the resolved target version.
 183	                agg_input.from = from.clone();
 184	                agg_input.to = Some(to.clone());
 185	                if let Some(reason) = outcome.reasons.get(id) {
 186	                    if let Some(source) = map_reason_to_change_source(reason, id, &to, &outcome, &agg) {
 187	                        agg_input.entries.push(ChangelogEntry { severity: sev, source });
 188	                    }
 189	                }
 190	                agg_input
 191	            } else if agg.pre_mode_recorded_only.contains(id) {
 192	                // Re-affirms an already-recorded pre-mode changeset, so no changelog entry is re-logged here.
 193	                ChangelogInput {
 194	                    package: id.clone(),
 195	                    from: from.clone(),
 196	                    to: Some(to.clone()),
 197	                    entries: Vec::new(),
 198	                }
 199	            } else {
 200	                // No changeset drove this bump (cascade, group, inference, pre-release).
 201	                // Synthesize a single entry describing the reason so that render_section()
 202	                // never receives an empty entries list (which returns EmptyInput).
 203	                let source = outcome
 204	                    .reasons
 205	                    .get(id)
 206	                    .and_then(|r| map_reason_to_change_source(r, id, &to, &outcome, &agg))
 207	                    .unwrap_or_else(|| ChangeSource::Changeset {
 208	                        filename: String::new(),
 209	                        summary: format!(
 210	                            "Version bump ({})",
 211	                            match sev {
 212	                                Severity::Major => "major",
 213	                                Severity::Minor => "minor",
 214	                                Severity::Patch => "patch",
 215	                                Severity::None => "none",
 216	                            }
 217	                        ),
 218	                    });
 219	                ChangelogInput {
 220	                    package: id.clone(),
 221	                    from: from.clone(),
 222	                    to: Some(to.clone()),
 223	                    entries: vec![ChangelogEntry { severity: sev, source }],
 224	                }
 225	            };
 226	
 227	            if let Some(group_name) = group_check
 228	                .new_members
 229	                .iter()
 230	                .find(|(_, members)| members.contains(id))
 231	                .map(|(name, _)| name.clone())
 232	            {
 233	                input.entries.push(ChangelogEntry {
 234	                    severity: sev,
 235	                    source: ChangeSource::NewGroupMember { group: group_name },
 236	                });
 237	            }
 238	
 239	            // An already-recorded pre-mode changeset with nothing else to log produces no entries; skip the write.
 240	            if !input.entries.is_empty() {
 241	                changelog_writes.push(crate::plan::ChangelogWrite {
 242	                    changelog_path: ch_path.clone(),
 243	                    input,
 244	                });
 245	            }
 246	        }
 247	    }
 248	
 249	    let is_pre_mode = pre_state
 250	        .as_ref()
 251	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
 252	        .unwrap_or(false);
 253	    // The "no pending changesets" warning fires only when no changeset, new or already recorded, is active this run.
 254	    let nothing_pending = if is_pre_mode {
 255	        !agg.pre_mode_has_active_changeset
 256	    } else {
 257	        agg.consumed.is_empty()
 258	    };
 259	
 260	    let mut diagnostics = outcome.diagnostics;
 261	    diagnostics.extend(group_check.diagnostics);
 262	    if nothing_pending && !opts.allow_empty_changesets && !ws.config.validation.allow_empty_changesets {
 263	        diagnostics.push(callisto_model::Diagnostic {
 264	            code: callisto_model::DiagnosticCode::EmptyChangeset,
 265	            severity: callisto_model::DiagnosticSeverity::Warning,
 266	            message: "No pending changesets found in workspace".to_string(),
 267	            package: None,
 268	            path: None,
 269	            escalated_by: Some(callisto_model::StrictFlag::Strict),
 270	            governed_by: Some(callisto_model::ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS),
 271	        });
 272	    }
 273	
 274	    escalate(&mut diagnostics, opts.strict);
 275	
 276	    let (pre_state_update, delete_pre_json) = if let Some(mut state) = pre_state {
 277	        if state.mode == callisto_model::format::PreMode::Exit {
 278	            (None, Some(ws.config.pre_json_path()))
 279	        } else {
 280	            // Records ids aggregate() determined are newly-seen this run; see Aggregation::new_pre_changesets.
 281	            for id in &agg.new_pre_changesets {
 282	                if !state.changesets.iter().any(|s| s == id) {
 283	                    state.changesets.push(id.clone());
 284	                }
 285	            }
 286	            (Some(state), None)
 287	        }
 288	    } else {
 289	        (None, None)
 290	    };
 291	
 292	    let targets = bumps.iter().map(|b| (b.package.clone(), b.to.clone())).collect();
 293	    let (platform_writes, optional_dep_updates) = platform_version_writes(ws, &targets)?;
 294	
 295	    Ok(VersionPlan {
 296	        bumps,
 297	        rewrites: outcome.rewrites.into_values().collect(),
 298	        platform_writes,
 299	        optional_dep_updates,
 300	        changelog_writes,
 301	        consumed_changesets: agg.consumed,
 302	        pre_state_update,
 303	        pre_json_path: ws.config.pre_json_path(),
 304	        pre_json_original_text,
 305	        delete_pre_json,
 306	        pre_cursor_updates: Vec::new(),
 307	        observed_versions: base_versions,
 308	        diagnostics,
 309	    })
 310	}
