 499	/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
 500	fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
 501	    ws: &Workspace<'_, R, D>,
 502	    spec: &str,
 503	) -> Result<bool, GraphError> {
 504	    let output = ws
 505	        .runner
 506	        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
 507	        .map_err(GraphError::Command)?;
 508	    match output.exit_code {
 509	        Some(0) => Ok(true),
 510	        Some(1) => Ok(false),
 511	        exit_code => Err(GraphError::Command(callisto_model::CommandError::Failed {
 512	            program: "git".to_string(),
 513	            exit_code,
 514	            stderr: output.stderr,
 515	        })),
 516	    }
 517	}
