 519	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
 520	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
 521	    ws: &Workspace<'_, R, D>,
 522	    head: &str,
 523	) -> Result<bool, GraphError> {
 524	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
 525	    let spec = format!("{head}:{dir}");
 526	    if !head_object_exists(ws, &spec)? {
 527	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
 528	        return Ok(false);
 529	    }
 530	    let output = ws
 531	        .runner
 532	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
 533	        .map_err(GraphError::Command)?;
 534	    if !output.success() {
 535	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
 536	            program: "git".to_string(),
 537	            exit_code: output.exit_code,
 538	            stderr: output.stderr,
 539	        }));
 540	    }
 541	    Ok(output.stdout.lines().any(|name| {
 542	        let name = name.trim();
 543	        name.ends_with(".md") && name != "README.md"
 544	    }))
 545	}
