 614	    ws: &Workspace<'_, R, D>,
 615	    path: &str,
 616	    cargo_root: Option<&str>,
 617	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
 618	    let manifest_path = std::path::Path::new(path);
 619	    let Ok(format) = callisto_model::ManifestFormat::from_path(manifest_path) else {
 620	        return Ok(None);
 621	    };
 622	    let Some(source) = manifest_blob_in_index(ws, path)? else {
 623	        return Ok(None);
