 432	/// True when an untracked or tracked changeset remains in the configured directory on disk.
 433	fn working_tree_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
 434	    ws: &Workspace<'_, R, D>,
 435	) -> Result<bool, GraphError> {
 436	    let dir = ws.root.join(&ws.config.changesets_dir);
 437	    let entries = match std::fs::read_dir(&dir) {
 438	        Ok(entries) => entries,
 439	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
 440	        Err(error) => {
 441	            return Err(GraphError::ApplyIo {
 442	                path: ws.config.changesets_dir.clone(),
 443	                message: error.to_string(),
 444	            })
 445	        }
 446	    };
 447	    for entry in entries {
 448	        let entry = entry.map_err(|error| GraphError::ApplyIo {
 449	            path: ws.config.changesets_dir.clone(),
 450	            message: error.to_string(),
 451	        })?;
 452	        let name = entry.file_name();
 453	        let name = name.to_string_lossy();
 454	        let is_file = entry.file_type().map_err(|error| GraphError::ApplyIo {
 455	            path: ws.config.changesets_dir.join(&*name),
 456	            message: error.to_string(),
 457	        })?;
 458	        if is_file.is_file() && name.ends_with(".md") && name != "README.md" {
 459	            return Ok(true);
 460	        }
 461	    }
 462	    Ok(false)
 463	}
