 465	/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
 466	fn canonical_manifest_staged_paths<R: CommandRunner, D: DependencyResolver>(
 467	    ws: &Workspace<'_, R, D>,
 468	) -> Result<BTreeSet<String>, GraphError> {
 469	    let mut paths = BTreeSet::new();
 470	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
 471	        paths.insert(super::release_decision::normalized_git_path(&decl.path)?);
 472	        if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
 473	            paths.insert("Cargo.toml".to_string());
 474	        }
 475	    }
 476	    let mut staged = BTreeSet::new();
 477	    for path in paths {
 478	        let output = ws
 479	            .runner
 480	            .run("git", &["diff", "--cached", "--quiet", "--", &path], &ws.root)
 481	            .map_err(GraphError::Command)?;
 482	        match output.exit_code {
 483	            Some(0) => {}
 484	            Some(1) => {
 485	                staged.insert(path);
 486	            }
 487	            exit_code => {
 488	                return Err(GraphError::Command(callisto_model::CommandError::Failed {
 489	                    program: "git".to_string(),
 490	                    exit_code,
 491	                    stderr: output.stderr,
 492	                }))
 493	            }
 494	        }
 495	    }
 496	    Ok(staged)
 497	}
