 547	fn manifest_blob_at<R: CommandRunner, D: DependencyResolver>(
 548	    ws: &Workspace<'_, R, D>,
 549	    head: &str,
 550	    path: &str,
 551	) -> Result<Option<String>, GraphError> {
 552	    let spec = format!("{head}:{path}");
 553	    if !head_object_exists(ws, &spec)? {
 554	        return Ok(None);
 555	    }
 556	    let output = ws
 557	        .runner
 558	        .run("git", &["show", &spec], &ws.root)
 559	        .map_err(GraphError::Command)?;
 560	    if !output.success() {
 561	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
 562	            program: "git".to_string(),
 563	            exit_code: output.exit_code,
 564	            stderr: output.stderr,
 565	        }));
 566	    }
 567	    Ok(Some(output.stdout))
 568	}
