 592	fn manifest_version_at<R: CommandRunner, D: DependencyResolver>(
 593	    ws: &Workspace<'_, R, D>,
 594	    head: &str,
 595	    path: &str,
 596	    cargo_root: Option<&str>,
 597	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
 598	    let path = std::path::Path::new(path);
 599	    let Ok(format) = callisto_model::ManifestFormat::from_path(path) else {
 600	        return Ok(None);
 601	    };
 602	    let Some(source) = manifest_blob_at(ws, head, &path.to_string_lossy())? else {
 603	        return Ok(None);
 604	    };
 605	    Ok(callisto_manifests::read_effective_version(
 606	        format,
 607	        &source,
 608	        path,
 609	        cargo_root.map(|source| (std::path::Path::new("Cargo.toml"), source)),
 610	    )?)
 611	}
