 634	/// Platform manifest version writes and owner `optionalDependencies` pin updates
 635	/// for every owner with a target version in `targets`. Sources: each owner's
 636	/// attached platform manifests, plus `[[fixed-group]]`
 637	/// platform members.
 638	pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
 639	    ws: &Workspace<'_, R, D>,
 640	    targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
 641	) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
 642	    let open_ctx = OpenContext::for_workspace_root(&ws.root);
 643	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
 644	
 645	    let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
 646	    for pkg in ws.graph.packages() {
 647	        members.extend(
 648	            ws.identity
 649	                .attached_platforms(pkg)
 650	                .map(|(name, path)| (&pkg.id, path, name)),
 651	        );
 652	    }
 653	    for group in ws.config.groups.fixed.values() {
 654	        for member in group.members(GroupMemberKind::PlatformManifest) {
 655	            if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
 656	                members.push((owner, path, name));
 657	            }
 658	        }
 659	    }
 660	
 661	    let mut seen = HashSet::new();
 662	    let mut platform_writes = Vec::new();
 663	    let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
 664	        std::collections::BTreeMap::new();
 665	    for (owner, path, name) in members {
 666	        let Some(to) = targets.get(owner) else {
 667	            continue;
 668	        };
 669	        if !seen.insert(path) {
 670	            continue;
 671	        }
 672	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
 673	        let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
 674	        let handle = open(&decl, &open_ctx)?;
 675	        let current = handle.current_version()?;
 676	        platform_writes.push(PlatformWrite {
 677	            manifest: path.to_path_buf(),
 678	            version: to.clone(),
 679	            from: current,
 680	        });
 681	
 682	        // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
 683	        for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
 684	            let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
 685	            let owner_manifest_decl =
 686	                callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
 687	            // Cached: owner manifest is shared across every platform target under it.
 688	            let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
 689	            if owner_handle
 690	                .iter_dependencies()
 691	                .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
 692	            {
 693	                optional_dep_map
 694	                    .entry(owner_decl.path.clone())
 695	                    .or_default()
 696	                    .push((name.to_string(), to.clone()));
 697	                break;
 698	            }
 699	        }
 700	    }
 701	    let optional_dep_updates = optional_dep_map
 702	        .into_iter()
 703	        .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
 704	        .collect();
 705	    Ok((platform_writes, optional_dep_updates))
 706	}
