    75	    let base_versions = ws.base_versions()?;
    76	    let tags = ws.tags()?;
    77	
    78	    let pre_path = ws.root.join(ws.config.pre_json_path());
    79	    let (pre_state, pre_json_original_text) = if pre_path.exists() {
    80	        let text =
    81	            std::fs::read_to_string(&pre_path).map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
