   119	    let input = CascadeInput {
   120	        graph: &ws.graph,
   121	        groups: &ws.config.groups,
   122	        cfg: &ws.config.cascade,
   123	        seed: &agg.severities,
   124	        reasons: &agg.reasons,
   125	        named_by: &agg.named_by,
   126	        base: &base_versions,
   127	        pre: pre_state.as_ref(),
   128	        tags,
   129	        identity: &ws.identity,
