   137	
   138	    let mut bumps = Vec::new();
   139	    let mut changelog_writes = Vec::new();
   140	
   141	    // PERF-006: build a map once so each lookup inside the loop is O(1)
   142	    // instead of O(N) (the previous packages().find() call).
   143	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
