   254	    let nothing_pending = if is_pre_mode {
   255	        !agg.pre_mode_has_active_changeset
   256	    } else {
   257	        agg.consumed.is_empty()
   258	    };
   259	
   260	    let mut diagnostics = outcome.diagnostics;
   261	    diagnostics.extend(group_check.diagnostics);
   262	    if nothing_pending && !opts.allow_empty_changesets && !ws.config.validation.allow_empty_changesets {
   263	        diagnostics.push(callisto_model::Diagnostic {
   264	            code: callisto_model::DiagnosticCode::EmptyChangeset,
   265	            severity: callisto_model::DiagnosticSeverity::Warning,
   266	            message: "No pending changesets found in workspace".to_string(),
   267	            package: None,
   268	            path: None,
   269	            escalated_by: Some(callisto_model::StrictFlag::Strict),
   270	            governed_by: Some(callisto_model::ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS),
   271	        });
   272	    }
   273	
   274	    escalate(&mut diagnostics, opts.strict);
