 116	/// Writes `plan` to disk and stages the touched paths in git.
 117	///
 118	/// Every side effect here is unconditional -- whether to apply at all is
 119	/// the caller's decision, which is why an [`ApplyPermit`] is required
 120	/// rather than a `dry_run` bool: a bool carries no guarantee any caller
 121	/// actually consulted it. A dry-run caller can't obtain a permit and
 122	/// simply doesn't call this function; it reports `plan` instead.
 123	///
 124	/// # Errors
 125	///
 126	/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
 127	/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
 128	/// - I/O errors writing changelog sections or `pre.json`.
 129	pub fn apply_version_plan<R: CommandRunner>(
 130	    root: &Path,
 131	    plan: &VersionPlan,
 132	    runner: &R,
 133	    opts: &ApplyOptions,
 134	    permit: &ApplyPermit,
 135	) -> Result<ApplyOutcome, GraphError> {
 136	    let mut outcome = ApplyOutcome::default();
 137	    let mut modified_paths = Vec::new();
 138	    let mut deferred_deletions = Vec::new();
 139	
 140	    let ctx = OpenContext::for_workspace_root(root);
 141	
 142	    let classification = classify_manifest_writes(plan);
 143	
 144	    for (path, group) in &classification.batched {
 145	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
 146	        let decl = callisto_model::ManifestDecl::new(path.clone(), ManifestRole::Canonical, fmt)?;
 147	        let mut handle = open(&decl, &ctx)?;
 148	        let mut mutated = false;
 149	
 150	        if let Some((bump_idx, target_version)) = &group.bump {
 151	            let bump = &plan.bumps[*bump_idx];
 152	            let current = handle.current_version()?;
 153	            if current == *target_version {
 154	                // Already at target — skip write, fall through to rewrites.
 155	            } else if current == bump.from {
 156	                handle.write_version(target_version, permit)?;
 157	                mutated = true;
 158	            } else {
 159	                return Err(GraphError::UnexpectedManifestVersion {
 160	                    path: path.clone(),
 161	                    expected_from: bump.from.clone(),
 162	                    expected_to: bump.to.clone(),
 163	                    found: current,
 164	                });
 165	            }
 166	        }
 167	
 168	        for rewrite_idx in &group.rewrite_indices {
 169	            let rewrite = &plan.rewrites[*rewrite_idx];
 170	            handle.update_dependency_spec(
 171	                &rewrite.key.name,
 172	                rewrite.key.kind.unwrap_or(callisto_model::DepKind::Runtime),
 173	                rewrite.to.clone(),
 174	                permit,
 175	            )?;
 176	            mutated = true;
 177	        }
 178	
 179	        if mutated {
 180	            handle.persist(permit)?;
 181	        }
 182	        modified_paths.push(path.clone());
 183	    }
 184	
 185	    // Root-manifest paths written exclusively through WorkspaceCargoResolver
 186	    // (no competing Manifest-trait write to the same physical file, i.e. not
 187	    // in `classification.excluded`): open once, apply the bump (if any) then
 188	    // every rewrite in memory, and persist exactly once -- mirroring the
 189	    // `classification.batched` loop above, but via WorkspaceCargoResolver
 190	    // instead of `open()`. `CargoWorkspacePackage`/`CargoWorkspaceDependency`
 191	    // writes have never had an idempotency precondition check (unlike
 192	    // `VersionWriteTarget::Manifest`/`DepWriteTarget::Manifest`), so none is
 193	    // introduced here -- both continue to write unconditionally.
 194	    for (root_manifest, group) in &classification.resolver_batched {
 195	        let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
 196	        let mut mutated = false;
 197	
 198	        if let Some((_, target_version)) = &group.bump {
 199	            ws_res.write_version(target_version, permit)?;
 200	            mutated = true;
 201	        }
 202	
 203	        for rewrite_idx in &group.rewrite_indices {
 204	            let rewrite = &plan.rewrites[*rewrite_idx];
 205	            ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
 206	            mutated = true;
 207	        }
 208	
 209	        if mutated {
 210	            ws_res.persist(permit)?;
 211	        }
 212	        modified_paths.push(root_manifest.clone());
 213	    }
 214	
 215	    for bump in &plan.bumps {
 216	        for write in &bump.writes {
 217	            match write {
 218	                VersionWriteTarget::Manifest(p) => {
 219	                    if !classification.excluded.contains(p) {
 220	                        continue;
 221	                    }
 222	                    let fmt = callisto_model::ManifestFormat::from_path(p)?;
 223	                    let decl = callisto_model::ManifestDecl::new(p.clone(), ManifestRole::Canonical, fmt)?;
 224	                    let mut handle = open(&decl, &ctx)?;
 225	                    let current = handle.current_version()?;
 226	                    if current == bump.to {
 227	                        // Already at target — skip write but still stage so git add re-stages on retry.
 228	                    } else if current == bump.from {
 229	                        handle.write_version(&bump.to, permit)?;
 230	                        handle.persist(permit)?;
 231	                    } else {
 232	                        return Err(GraphError::UnexpectedManifestVersion {
 233	                            path: p.clone(),
 234	                            expected_from: bump.from.clone(),
 235	                            expected_to: bump.to.clone(),
 236	                            found: current,
 237	                        });
 238	                    }
 239	                    modified_paths.push(p.clone());
 240	                }
 241	                VersionWriteTarget::CargoWorkspacePackage { root_manifest } => {
 242	                    if classification.resolver_batched.contains_key(root_manifest) {
 243	                        // Already applied and persisted by the resolver-batched loop above.
 244	                        continue;
 245	                    }
 246	                    let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
 247	                    ws_res.write_version(&bump.to, permit)?;
 248	                    ws_res.persist(permit)?;
 249	                    modified_paths.push(root_manifest.clone());
 250	                }
 251	            }
 252	        }
 253	    }
 254	
 255	    for rewrite in &plan.rewrites {
 256	        match &rewrite.key.target {
 257	            DepWriteTarget::Manifest(p) => {
 258	                if !classification.excluded.contains(p) {
 259	                    continue;
 260	                }
 261	                let fmt = callisto_model::ManifestFormat::from_path(p)?;
 262	                let decl = callisto_model::ManifestDecl::new(p.clone(), ManifestRole::Canonical, fmt)?;
 263	                let mut handle = open(&decl, &ctx)?;
 264	                handle.update_dependency_spec(
 265	                    &rewrite.key.name,
 266	                    rewrite.key.kind.unwrap_or(callisto_model::DepKind::Runtime),
 267	                    rewrite.to.clone(),
 268	                    permit,
 269	                )?;
 270	                handle.persist(permit)?;
 271	                modified_paths.push(p.clone());
 272	            }
 273	            DepWriteTarget::CargoWorkspaceDependency { root_manifest } => {
 274	                if classification.resolver_batched.contains_key(root_manifest) {
 275	                    // Already applied and persisted by the resolver-batched loop above.
 276	                    continue;
 277	                }
 278	                let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
 279	                ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
 280	                ws_res.persist(permit)?;
 281	                modified_paths.push(root_manifest.clone());
 282	            }
 283	        }
 284	    }
 285	
 286	    for pw in &plan.platform_writes {
 287	        let fmt = callisto_model::ManifestFormat::from_path(&pw.manifest)?;
 288	        let decl = callisto_model::ManifestDecl::new(pw.manifest.clone(), ManifestRole::Canonical, fmt)?;
 289	        let mut handle = open(&decl, &ctx)?;
 290	        let current = handle.current_version()?;
 291	        if current == pw.version {
 292	            // Already at target — skip write, but still stage so git add re-stages on retry.
 293	        } else if current == pw.from {
 294	            handle.write_version(&pw.version, permit)?;
 295	            handle.persist(permit)?;
 296	        } else {
 297	            return Err(GraphError::UnexpectedManifestVersion {
 298	                path: pw.manifest.clone(),
 299	                expected_from: pw.from.clone(),
 300	                expected_to: pw.version.clone(),
 301	                found: current,
 302	            });
 303	        }
 304	        modified_paths.push(pw.manifest.clone());
 305	    }
 306	
 307	    for opt in &plan.optional_dep_updates {
 308	        let fmt = callisto_model::ManifestFormat::from_path(&opt.manifest)?;
 309	        let decl = callisto_model::ManifestDecl::new(opt.manifest.clone(), ManifestRole::Canonical, fmt)?;
 310	        let mut handle = open(&decl, &ctx)?;
 311	        handle.update_optional_dependencies(&opt.updates, permit)?;
 312	        handle.persist(permit)?;
 313	        modified_paths.push(opt.manifest.clone());
 314	    }
 315	
 316	    if !opts.transient {
 317	        for cl in &plan.changelog_writes {
 318	            let rendered = crate::changelog::render_section(&cl.input)?;
 319	            crate::changelog::prepend(
 320	                root,
 321	                &cl.changelog_path,
 322	                &cl.input.package.display_name(),
 323	                &rendered,
 324	                permit,
 325	            )?;
 326	            modified_paths.push(cl.changelog_path.clone());
 327	        }
 328	
 329	        for cs_path in &plan.consumed_changesets {
 330	            deferred_deletions.push(cs_path.clone());
 331	        }
 332	
 333	        if let Some(ref pre_state) = plan.pre_state_update {
 334	            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
 335	            let rel_pre_path = plan.pre_json_path.clone();
 336	            let pre_path = root.join(&rel_pre_path);
 337	            let text = match &plan.pre_json_original_text {
 338	                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
 339	                None => callisto_model::format::write_pre_json(pre_state),
 340	            };
 341	            callisto_manifests::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
 342	                path: rel_pre_path.clone(),
 343	                message: e.to_string(),
 344	            })?;
 345	            modified_paths.push(rel_pre_path);
 346	        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
 347	            deferred_deletions.push(rel_pre_path.clone());
 348	        }
 349	    }
 350	
 351	    // Collect the set of ecosystems actively involved in this plan so that
 352	    // only the corresponding lockfiles are staged. Staging lockfiles whose
 353	    // ecosystem was not touched can sweep up unrelated user changes.
 354	    use callisto_model::Ecosystem;
 355	    let active_ecosystems: std::collections::HashSet<Ecosystem> = plan
 356	        .bumps
 357	        .iter()
 358	        .flat_map(|bump| {
 359	            bump.package
 360	                .ecosystem()
 361	                .into_iter()
 362	                .chain(bump.writes.iter().filter_map(|write| {
 363	                    match write {
 364	                        VersionWriteTarget::CargoWorkspacePackage { .. } => Some(Ecosystem::Cargo),
 365	                        VersionWriteTarget::Manifest(path) => callisto_model::ManifestFormat::from_path(path)
 366	                            .ok()
 367	                            .map(|fmt| fmt.ecosystem()),
 368	                    }
 369	                }))
 370	        })
 371	        .chain(plan.rewrites.iter().filter_map(|rewrite| {
 372	            match &rewrite.key.target {
 373	                DepWriteTarget::CargoWorkspaceDependency { .. } => Some(Ecosystem::Cargo),
 374	                DepWriteTarget::Manifest(path) => callisto_model::ManifestFormat::from_path(path)
 375	                    .ok()
 376	                    .map(|fmt| fmt.ecosystem()),
 377	            }
 378	        }))
 379	        .chain(
 380	            plan.platform_writes
 381	                .iter()
 382	                .filter_map(|write| callisto_model::ManifestFormat::from_path(&write.manifest).ok())
 383	                .map(|fmt| fmt.ecosystem()),
 384	        )
 385	        .chain(
 386	            plan.optional_dep_updates
 387	                .iter()
 388	                .filter_map(|update| callisto_model::ManifestFormat::from_path(&update.manifest).ok())
 389	                .map(|fmt| fmt.ecosystem()),
 390	        )
 391	        .collect();
 392	
 393	    // Must run before the git-staging loop below, so refreshed lockfiles are on disk to be staged.
 394	    if opts.refresh_lockfiles {
 395	        let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();
 396	
 397	        if active_ecosystems.contains(&Ecosystem::Cargo) {
 398	            refresh_results.push(run_lockfile_refresh(
 399	                runner,
 400	                root,
 401	                "Cargo.lock",
 402	                "cargo",
 403	                &["update", "--workspace"],
 404	            )?);
 405	        }
 406	
 407	        if active_ecosystems.contains(&Ecosystem::Pypi) {
 408	            if root.join("uv.lock").exists() {
 409	                refresh_results.push(run_lockfile_refresh(runner, root, "uv.lock", "uv", &["lock"])?);
 410	            } else if root.join("poetry.lock").exists() {
 411	                refresh_results.push(run_lockfile_refresh(
 412	                    runner,
 413	                    root,
 414	                    "poetry.lock",
 415	                    "poetry",
 416	                    &["lock", "--no-update"],
 417	                )?);
 418	            } else if root.join("pdm.lock").exists() {
 419	                refresh_results.push(run_lockfile_refresh(
 420	                    runner,
 421	                    root,
 422	                    "pdm.lock",
 423	                    "pdm",
 424	                    &["lock", "--update-reuse"],
 425	                )?);
 426	            }
 427	        }
 428	
 429	        if active_ecosystems.contains(&Ecosystem::Npm) {
 430	            if root.join("package-lock.json").exists() {
 431	                refresh_results.push(run_lockfile_refresh(
 432	                    runner,
 433	                    root,
 434	                    "package-lock.json",
 435	                    "npm",
 436	                    &["install", "--package-lock-only", "--ignore-scripts"],
 437	                )?);
 438	            }
 439	            if root.join("pnpm-lock.yaml").exists() {
 440	                refresh_results.push(run_lockfile_refresh(
 441	                    runner,
 442	                    root,
 443	                    "pnpm-lock.yaml",
 444	                    "pnpm",
 445	                    &["install", "--lockfile-only"],
 446	                )?);
 447	            }
 448	            if root.join("yarn.lock").exists() {
 449	                refresh_results.push(run_lockfile_refresh(
 450	                    runner,
 451	                    root,
 452	                    "yarn.lock",
 453	                    "yarn",
 454	                    &["install", "--mode", "update-lockfile"],
 455	                )?);
 456	            }
 457	            if root.join("bun.lock").exists() {
 458	                refresh_results.push(run_lockfile_refresh(
 459	                    runner,
 460	                    root,
 461	                    "bun.lock",
 462	                    "bun",
 463	                    &["install", "--lockfile-only"],
 464	                )?);
 465	            } else if root.join("bun.lockb").exists() {
 466	                refresh_results.push(run_lockfile_refresh(
 467	                    runner,
 468	                    root,
 469	                    "bun.lockb",
 470	                    "bun",
 471	                    &["install", "--lockfile-only"],
 472	                )?);
 473	            }
 474	        }
 475	
 476	        if !refresh_results.is_empty() {
 477	            outcome.lockfile_refresh_results = Some(refresh_results);
 478	        }
 479	    }
 480	
 481	    // Map each well-known lockfile to its ecosystem, then include the file
 482	    // only when that ecosystem is active and the file exists on disk.
 483	    let lockfile_ecosystems: &[(&str, Ecosystem)] = &[
 484	        ("Cargo.lock", Ecosystem::Cargo),
 485	        ("package-lock.json", Ecosystem::Npm),
 486	        ("pnpm-lock.yaml", Ecosystem::Npm),
 487	        ("yarn.lock", Ecosystem::Npm),
 488	        ("bun.lock", Ecosystem::Npm),
 489	        ("bun.lockb", Ecosystem::Npm),
 490	        ("uv.lock", Ecosystem::Pypi),
 491	        ("poetry.lock", Ecosystem::Pypi),
 492	        ("pdm.lock", Ecosystem::Pypi),
 493	        ("Pipfile.lock", Ecosystem::Pypi),
 494	    ];
 495	    for (lockfile, ecosystem) in lockfile_ecosystems {
 496	        if !active_ecosystems.contains(ecosystem) {
 497	            continue;
 498	        }
 499	        let p = PathBuf::from(lockfile);
 500	        if root.join(&p).exists() && !modified_paths.contains(&p) {
 501	            modified_paths.push(p);
 502	        }
 503	    }
 504	
 505	    if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
 506	        // Stage all written release state before consuming its inputs. If a refresh or add fails,
 507	        // the changesets/pre-state remain available; if removal staging fails, the manifest diff
 508	        // still identifies the interrupted run.
 509	        let (existing, deleted): (Vec<_>, Vec<_>) = modified_paths.iter().partition(|p| root.join(p).exists());
 510	
 511	        if !existing.is_empty() {
 512	            let mut args = vec!["add", "--"];
 513	            let strs: Vec<String> = existing.iter().map(|p| p.display().to_string()).collect();
 514	            for s in &strs {
 515	                args.push(s);
 516	            }
 517	            let output = runner.run("git", &args, root)?;
 518	            if !output.success() {
 519	                return Err(GraphError::Command(CommandError::Failed {
 520	                    program: "git".to_string(),
 521	                    exit_code: output.exit_code,
 522	                    stderr: output.redacted_stderr(),
 523	                }));
 524	            }
 525	        }
 526	
 527	        if !deleted.is_empty() {
 528	            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
 529	            let strs: Vec<String> = deleted.iter().map(|p| p.display().to_string()).collect();
 530	            for s in &strs {
 531	                args.push(s);
 532	            }
 533	            let output = runner.run("git", &args, root)?;
 534	            if !output.success() {
 535	                return Err(GraphError::Command(CommandError::Failed {
 536	                    program: "git".to_string(),
 537	                    exit_code: output.exit_code,
 538	                    stderr: output.redacted_stderr(),
 539	                }));
 540	            }
 541	        }
 542	
 543	        if !deferred_deletions.is_empty() {
 544	            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
 545	            let strs: Vec<String> = deferred_deletions.iter().map(|p| p.display().to_string()).collect();
 546	            for s in &strs {
 547	                args.push(s);
 548	            }
 549	            let output = runner.run("git", &args, root)?;
 550	            if !output.success() {
 551	                return Err(GraphError::Command(CommandError::Failed {
 552	                    program: "git".to_string(),
 553	                    exit_code: output.exit_code,
 554	                    stderr: output.redacted_stderr(),
 555	                }));
 556	            }
 557	
 558	            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
 559	            for path in &deferred_deletions {
 560	                let full = root.join(path);
 561	                if full.exists() {
 562	                    fs::remove_file(&full).map_err(|e| GraphError::ApplyIo {
 563	                        path: path.clone(),
 564	                        message: e.to_string(),
 565	                    })?;
 566	                }
 567	            }
 568	            modified_paths.extend(deferred_deletions.iter().cloned());
 569	        }
 570	
 571	        outcome.staged = modified_paths;
 572	    }
 573	
 574	    Ok(outcome)
 575	}
