 577	/// Maps a non-zero exit to `GraphError::LockfileRefreshFailed`, an exec failure to `GraphError::Command`.
 578	fn run_lockfile_refresh<R: CommandRunner>(
 579	    runner: &R,
 580	    root: &Path,
 581	    filename: &str,
 582	    program: &str,
 583	    args: &[&str],
 584	) -> Result<LockfileRefreshResult, GraphError> {
 585	    let refresh_command = format!("{program} {}", args.join(" "));
 586	    let out = runner.run(program, args, root)?;
 587	    if !out.success() {
 588	        return Err(GraphError::LockfileRefreshFailed {
 589	            filename: PathBuf::from(filename),
 590	            refresh_command,
 591	            exit_code: out.exit_code,
 592	            stderr: out.redacted_stderr(),
 593	        });
 594	    }
 595	    Ok(LockfileRefreshResult {
 596	        filename: PathBuf::from(filename),
 597	        refresh_command,
 598	        success: true,
 599	        exit_code: out.exit_code,
 600	    })
 601	}
