 617	
 618	    impl CommandRunner for NoopRunner {
 619	        fn run(&self, _program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
 620	            Ok(CommandOutput {
 621	                exit_code: Some(0),
