 635	
 636	    impl CommandRunner for RecordingRunner {
 637	        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
 638	            self.calls
 639	                .lock()
 640	                .unwrap()
 641	                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));
