  38	#[derive(Debug, Default)]
  39	pub(crate) struct ManifestWriteClassification {
  40	    pub(crate) batched: BTreeMap<PathBuf, ManifestWriteGroup>,
  41	    /// Root-manifest paths written exclusively through
  42	    /// `WorkspaceCargoResolver` (`CargoWorkspacePackage`/
  43	    /// `CargoWorkspaceDependency` targets), with no competing write to the
  44	    /// same physical file through the `Manifest` trait's `open()` path.
  45	    /// Consumed the same way as `batched`, but via `WorkspaceCargoResolver`
  46	    /// instead of `open()` -- see `apply_version_plan`'s resolver-batched
  47	    /// loop.
  48	    pub(crate) resolver_batched: BTreeMap<PathBuf, ManifestWriteGroup>,
  49	    /// Paths that receive writes through BOTH the `Manifest` trait and
  50	    /// `WorkspaceCargoResolver` -- the mixed-routing data-loss/ordering
  51	    /// hazard.
  52	    /// Never batched on either side; each write is applied individually,
  53	    /// strictly in plan order, exactly as before this change.
  54	    pub(crate) excluded: BTreeSet<PathBuf>,
  55	}
  56	
  57	pub(crate) fn classify_manifest_writes(plan: &VersionPlan) -> ManifestWriteClassification {
  58	    let mut resolver_by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
  59	    for (idx, bump) in plan.bumps.iter().enumerate() {
  60	        for write in &bump.writes {
  61	            if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
  62	                resolver_by_path.entry(root_manifest.clone()).or_default().bump = Some((idx, bump.to.clone()));
  63	            }
  64	        }
  65	    }
  66	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
  67	        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
  68	            resolver_by_path
  69	                .entry(root_manifest.clone())
  70	                .or_default()
  71	                .rewrite_indices
  72	                .push(idx);
  73	        }
  74	    }
  75	
  76	    let mut by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
  77	    for (idx, bump) in plan.bumps.iter().enumerate() {
  78	        for write in &bump.writes {
  79	            if let VersionWriteTarget::Manifest(p) = write {
  80	                by_path.entry(p.clone()).or_default().bump = Some((idx, bump.to.clone()));
  81	            }
  82	        }
  83	    }
  84	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
  85	        if let DepWriteTarget::Manifest(p) = &rewrite.key.target {
  86	            by_path.entry(p.clone()).or_default().rewrite_indices.push(idx);
  87	        }
  88	    }
  89	
  90	    let mut batched = BTreeMap::new();
  91	    let mut excluded = BTreeSet::new();
  92	    for (path, group) in by_path {
  93	        if resolver_by_path.contains_key(&path) {
  94	            excluded.insert(path);
  95	        } else {
  96	            batched.insert(path, group);
  97	        }
  98	    }
  99	
 100	    // Every path in `resolver_by_path` that isn't also mixed-routed
 101	    // (present in `excluded`) is safe to batch into one
 102	    // load/mutate*/persist cycle -- it's written exclusively through
 103	    // WorkspaceCargoResolver, never through the Manifest trait.
 104	    let resolver_batched: BTreeMap<PathBuf, ManifestWriteGroup> = resolver_by_path
 105	        .into_iter()
 106	        .filter(|(path, _)| !excluded.contains(path))
 107	        .collect();
 108	
 109	    ManifestWriteClassification {
 110	        batched,
 111	        resolver_batched,
 112	        excluded,
 113	    }
 114	}
