 310	        let mut handle = open(&decl, &ctx)?;
 311	        handle.update_optional_dependencies(&opt.updates, permit)?;
 312	        handle.persist(permit)?;
 313	        modified_paths.push(opt.manifest.clone());
 314	    }
 315	
 316	    if !opts.transient {
 317	        for cl in &plan.changelog_writes {
 318	            let rendered = crate::changelog::render_section(&cl.input)?;
 319	            crate::changelog::prepend(
 320	                root,
 321	                &cl.changelog_path,
 322	                &cl.input.package.display_name(),
 323	                &rendered,
 324	                permit,
 325	            )?;
 326	            modified_paths.push(cl.changelog_path.clone());
 327	        }
 328	
 329	        for cs_path in &plan.consumed_changesets {
 330	            deferred_deletions.push(cs_path.clone());
 331	        }
 332	
 333	        if let Some(ref pre_state) = plan.pre_state_update {
 334	            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
 335	            let rel_pre_path = plan.pre_json_path.clone();
 336	            let pre_path = root.join(&rel_pre_path);
 337	            let text = match &plan.pre_json_original_text {
 338	                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
 339	                None => callisto_model::format::write_pre_json(pre_state),
 340	            };
 341	            callisto_manifests::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
 342	                path: rel_pre_path.clone(),
 343	                message: e.to_string(),
 344	            })?;
 345	            modified_paths.push(rel_pre_path);
 346	        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
 347	            deferred_deletions.push(rel_pre_path.clone());
 348	        }
 349	    }
 350	
 351	    // Collect the set of ecosystems actively involved in this plan so that
 352	    // only the corresponding lockfiles are staged. Staging lockfiles whose
 353	    // ecosystem was not touched can sweep up unrelated user changes.
 354	    use callisto_model::Ecosystem;
 355	    let active_ecosystems: std::collections::HashSet<Ecosystem> = plan
 356	        .bumps
 357	        .iter()
 358	        .flat_map(|bump| {
 359	            bump.package
 360	                .ecosystem()
 361	                .into_iter()
 362	                .chain(bump.writes.iter().filter_map(|write| {
 363	                    match write {
 364	                        VersionWriteTarget::CargoWorkspacePackage { .. } => Some(Ecosystem::Cargo),
 365	                        VersionWriteTarget::Manifest(path) => callisto_model::ManifestFormat::from_path(path)
 366	                            .ok()
 367	                            .map(|fmt| fmt.ecosystem()),
 368	                    }
 369	                }))
 370	        })
 371	        .chain(plan.rewrites.iter().filter_map(|rewrite| {
 372	            match &rewrite.key.target {
 373	                DepWriteTarget::CargoWorkspaceDependency { .. } => Some(Ecosystem::Cargo),
 374	                DepWriteTarget::Manifest(path) => callisto_model::ManifestFormat::from_path(path)
 375	                    .ok()
 376	                    .map(|fmt| fmt.ecosystem()),
 377	            }
 378	        }))
 379	        .chain(
 380	            plan.platform_writes
 381	                .iter()
 382	                .filter_map(|write| callisto_model::ManifestFormat::from_path(&write.manifest).ok())
 383	                .map(|fmt| fmt.ecosystem()),
 384	        )
 385	        .chain(
 386	            plan.optional_dep_updates
 387	                .iter()
 388	                .filter_map(|update| callisto_model::ManifestFormat::from_path(&update.manifest).ok())
 389	                .map(|fmt| fmt.ecosystem()),
 390	        )
 391	        .collect();
 392	
 393	    // Must run before the git-staging loop below, so refreshed lockfiles are on disk to be staged.
 394	    if opts.refresh_lockfiles {
 395	        let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();
 396	
 397	        if active_ecosystems.contains(&Ecosystem::Cargo) {
 398	            refresh_results.push(run_lockfile_refresh(
 399	                runner,
 400	                root,
 401	                "Cargo.lock",
 402	                "cargo",
 403	                &["update", "--workspace"],
 404	            )?);
 405	        }
 406	
 407	        if active_ecosystems.contains(&Ecosystem::Pypi) {
 408	            if root.join("uv.lock").exists() {
 409	                refresh_results.push(run_lockfile_refresh(runner, root, "uv.lock", "uv", &["lock"])?);
 410	            } else if root.join("poetry.lock").exists() {
 411	                refresh_results.push(run_lockfile_refresh(
 412	                    runner,
 413	                    root,
 414	                    "poetry.lock",
 415	                    "poetry",
 416	                    &["lock", "--no-update"],
 417	                )?);
 418	            } else if root.join("pdm.lock").exists() {
 419	                refresh_results.push(run_lockfile_refresh(
 420	                    runner,
 421	                    root,
 422	                    "pdm.lock",
 423	                    "pdm",
 424	                    &["lock", "--update-reuse"],
 425	                )?);
 426	            }
 427	        }
 428	
 429	        if active_ecosystems.contains(&Ecosystem::Npm) {
 430	            if root.join("package-lock.json").exists() {
 431	                refresh_results.push(run_lockfile_refresh(
 432	                    runner,
 433	                    root,
 434	                    "package-lock.json",
 435	                    "npm",
 436	                    &["install", "--package-lock-only", "--ignore-scripts"],
 437	                )?);
 438	            }
 439	            if root.join("pnpm-lock.yaml").exists() {
 440	                refresh_results.push(run_lockfile_refresh(
 441	                    runner,
 442	                    root,
 443	                    "pnpm-lock.yaml",
 444	                    "pnpm",
 445	                    &["install", "--lockfile-only"],
 446	                )?);
 447	            }
 448	            if root.join("yarn.lock").exists() {
 449	                refresh_results.push(run_lockfile_refresh(
 450	                    runner,
 451	                    root,
 452	                    "yarn.lock",
 453	                    "yarn",
 454	                    &["install", "--mode", "update-lockfile"],
 455	                )?);
 456	            }
 457	            if root.join("bun.lock").exists() {
 458	                refresh_results.push(run_lockfile_refresh(
 459	                    runner,
 460	                    root,
 461	                    "bun.lock",
 462	                    "bun",
 463	                    &["install", "--lockfile-only"],
 464	                )?);
 465	            } else if root.join("bun.lockb").exists() {
 466	                refresh_results.push(run_lockfile_refresh(
 467	                    runner,
 468	                    root,
 469	                    "bun.lockb",
 470	                    "bun",
 471	                    &["install", "--lockfile-only"],
 472	                )?);
 473	            }
 474	        }
 475	
 476	        if !refresh_results.is_empty() {
 477	            outcome.lockfile_refresh_results = Some(refresh_results);
 478	        }
 479	    }
 480	
 481	    // Map each well-known lockfile to its ecosystem, then include the file
 482	    // only when that ecosystem is active and the file exists on disk.
 483	    let lockfile_ecosystems: &[(&str, Ecosystem)] = &[
 484	        ("Cargo.lock", Ecosystem::Cargo),
 485	        ("package-lock.json", Ecosystem::Npm),
 486	        ("pnpm-lock.yaml", Ecosystem::Npm),
 487	        ("yarn.lock", Ecosystem::Npm),
 488	        ("bun.lock", Ecosystem::Npm),
 489	        ("bun.lockb", Ecosystem::Npm),
 490	        ("uv.lock", Ecosystem::Pypi),
 491	        ("poetry.lock", Ecosystem::Pypi),
 492	        ("pdm.lock", Ecosystem::Pypi),
 493	        ("Pipfile.lock", Ecosystem::Pypi),
 494	    ];
 495	    for (lockfile, ecosystem) in lockfile_ecosystems {
 496	        if !active_ecosystems.contains(ecosystem) {
 497	            continue;
 498	        }
 499	        let p = PathBuf::from(lockfile);
 500	        if root.join(&p).exists() && !modified_paths.contains(&p) {
 501	            modified_paths.push(p);
 502	        }
 503	    }
 504	
 505	    if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
 506	        // Stage all written release state before consuming its inputs. If a refresh or add fails,
 507	        // the changesets/pre-state remain available; if removal staging fails, the manifest diff
 508	        // still identifies the interrupted run.
 509	        let (existing, deleted): (Vec<_>, Vec<_>) = modified_paths.iter().partition(|p| root.join(p).exists());
 510	
 511	        if !existing.is_empty() {
 512	            let mut args = vec!["add", "--"];
 513	            let strs: Vec<String> = existing.iter().map(|p| p.display().to_string()).collect();
 514	            for s in &strs {
 515	                args.push(s);
 516	            }
 517	            let output = runner.run("git", &args, root)?;
 518	            if !output.success() {
 519	                return Err(GraphError::Command(CommandError::Failed {
 520	                    program: "git".to_string(),
 521	                    exit_code: output.exit_code,
 522	                    stderr: output.redacted_stderr(),
 523	                }));
 524	            }
 525	        }
 526	
 527	        if !deleted.is_empty() {
 528	            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
 529	            let strs: Vec<String> = deleted.iter().map(|p| p.display().to_string()).collect();
 530	            for s in &strs {
 531	                args.push(s);
 532	            }
 533	            let output = runner.run("git", &args, root)?;
 534	            if !output.success() {
 535	                return Err(GraphError::Command(CommandError::Failed {
 536	                    program: "git".to_string(),
 537	                    exit_code: output.exit_code,
 538	                    stderr: output.redacted_stderr(),
 539	                }));
 540	            }
 541	        }
 542	
 543	        if !deferred_deletions.is_empty() {
 544	            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
 545	            let strs: Vec<String> = deferred_deletions.iter().map(|p| p.display().to_string()).collect();
 546	            for s in &strs {
 547	                args.push(s);
 548	            }
 549	            let output = runner.run("git", &args, root)?;
 550	            if !output.success() {
 551	                return Err(GraphError::Command(CommandError::Failed {
 552	                    program: "git".to_string(),
 553	                    exit_code: output.exit_code,
 554	                    stderr: output.redacted_stderr(),
 555	                }));
 556	            }
 557	
 558	            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
 559	            for path in &deferred_deletions {
 560	                let full = root.join(path);
 561	                if full.exists() {
 562	                    fs::remove_file(&full).map_err(|e| GraphError::ApplyIo {
 563	                        path: path.clone(),
 564	                        message: e.to_string(),
 565	                    })?;
 566	                }
 567	            }
 568	            modified_paths.extend(deferred_deletions.iter().cloned());
 569	        }
 570	
 571	        outcome.staged = modified_paths;
 572	    }
 573	
 574	    Ok(outcome)
 575	}
