1234	    /// A `CommandRunner` whose configured program always fails with a fixed
1235	    /// exit code and stderr; every other program succeeds.
1236	    struct FailingProgramRunner {
1237	        failing_program: &'static str,
1238	        exit_code: i32,
1239	        stderr: &'static str,
1240	    }
1241	
1242	    struct FailingGitRmRunner {
1243	        calls: std::sync::Arc<std::sync::Mutex<Vec<Vec<String>>>>,
1244	    }
1245	
1246	    impl CommandRunner for FailingGitRmRunner {
1247	        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
1248	            self.calls
1249	                .lock()
1250	                .unwrap()
1251	                .push(args.iter().map(|arg| (*arg).to_string()).collect());
1252	            let fails = program == "git" && args.first() == Some(&"rm");
1253	            Ok(CommandOutput {
1254	                exit_code: Some(if fails { 1 } else { 0 }),
1255	                stdout: String::new(),
1256	                stderr: if fails {
1257	                    "index removal failed".to_string()
1258	                } else {
1259	                    String::new()
1260	                },
1261	            })
1262	        }
1263	    }
1264	
1265	    impl CommandRunner for FailingProgramRunner {
1266	        fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
1267	            if program == self.failing_program {
1268	                return Ok(CommandOutput {
1269	                    exit_code: Some(self.exit_code),
1270	                    stdout: String::new(),
1271	                    stderr: self.stderr.to_string(),
1272	                });
1273	            }
1274	            Ok(CommandOutput {
1275	                exit_code: Some(0),
1276	                stdout: String::new(),
1277	                stderr: String::new(),
1278	            })
1279	        }
1280	    }
