2389	        use std::os::unix::fs::PermissionsExt;
2390	
2391	        let dir = tempfile::tempdir().unwrap();
2392	        let root = dir.path();
2393	
2394	        let a_dir = root.join("a-crate");
2395	        std::fs::create_dir_all(&a_dir).unwrap();
2396	        let a_path = a_dir.join("Cargo.toml");
2397	        let a_original = "[package]\nname = \"crate-a\"\nversion = \"1.0.0\"\nedition = \"2021\"\n";
2398	        std::fs::write(&a_path, a_original).unwrap();
2399	
2400	        let b_dir = root.join("b-crate");
2401	        std::fs::create_dir_all(&b_dir).unwrap();
2402	        let b_path = b_dir.join("Cargo.toml");
2403	        let b_original = "[package]\nname = \"crate-b\"\nversion = \"1.0.0\"\nedition = \"2021\"\n";
2404	        std::fs::write(&b_path, b_original).unwrap();
2405	
2406	        let a_rel = PathBuf::from("a-crate/Cargo.toml");
2407	        let b_rel = PathBuf::from("b-crate/Cargo.toml");
2408	
2409	        // b-crate's PlannedBump is listed FIRST and a-crate's SECOND, deliberately
2410	        // reversed from lexicographic path order, so plan-encounter order and
2411	        // BTreeMap path order disagree -- see this task's own reasoning.
2412	        let plan = VersionPlan {
2413	            bumps: vec![
2414	                PlannedBump {
2415	                    package: PackageId::parse("cargo:crate-b").unwrap(),
2416	                    from: cargo_version("1.0.0"),
2417	                    to: cargo_version("1.1.0"),
2418	                    severity: Severity::Minor,
2419	                    governed_by: None,
2420	                    reason: None,
2421	                    writes: vec![VersionWriteTarget::Manifest(b_rel.clone())],
2422	                },
2423	                PlannedBump {
2424	                    package: PackageId::parse("cargo:crate-a").unwrap(),
2425	                    from: cargo_version("1.0.0"),
2426	                    to: cargo_version("1.1.0"),
2427	                    severity: Severity::Minor,
2428	                    governed_by: None,
2429	                    reason: None,
2430	                    writes: vec![VersionWriteTarget::Manifest(a_rel.clone())],
2431	                },
2432	            ],
2433	            ..Default::default()
2434	        };
2435	
2436	        let permit = ApplyPermit::force_for_tests();
2437	        let opts = ApplyOptions::default();
2438	
2439	        let original_mode = std::fs::metadata(&b_dir).unwrap().permissions().mode();
2440	        std::fs::set_permissions(&b_dir, std::fs::Permissions::from_mode(0o555)).unwrap();
2441	
2442	        let probe_path = b_dir.join(".rtk-write-probe");
2443	        let probe_write_succeeded = std::fs::write(&probe_path, b"probe").is_ok();
2444	        if probe_write_succeeded {
2445	            std::fs::remove_file(&probe_path).ok();
2446	            std::fs::set_permissions(&b_dir, std::fs::Permissions::from_mode(original_mode)).unwrap();
2447	            eprintln!(
2448	                "skipping batched_groups_process_strictly_sequentially_in_btreemap_path_order: \
2449	                 process can write into a 0o555 directory (likely running as root); chmod-based failure injection is a no-op here"
2450	            );
2451	            return;
2452	        }
2453	
2454	        let result = apply_version_plan(root, &plan, &NoopRunner, &opts, &permit);
2455	
2456	        std::fs::set_permissions(&b_dir, std::fs::Permissions::from_mode(original_mode)).unwrap();
2457	
2458	        assert!(
2459	            matches!(
2460	                result,
2461	                Err(GraphError::Manifest(callisto_model::ManifestError::Write { .. }))
2462	            ),
2463	            "b-crate's persist failure must propagate; got: {result:?}"
2464	        );
2465	
2466	        let a_on_disk = std::fs::read_to_string(&a_path).unwrap();
2467	        assert!(
2468	            a_on_disk.contains("version = \"1.1.0\""),
2469	            "a-crate sorts first, so it must be fully persisted before b-crate is attempted; got:\n{a_on_disk}"
2470	        );
2471	
2472	        let b_on_disk = std::fs::read_to_string(&b_path).unwrap();
2473	        assert_eq!(
2474	            b_on_disk, b_original,
2475	            "b-crate must be byte-for-byte unchanged since its persist never succeeded"
2476	        );
2477	    }
