 11	#[test]
 12	fn test_pre_mode_blackbox_lifecycle() {
 13	    let dir = setup_polyglot_git_repo();
 14	    let root = dir.path();
 15	
 16	    let global = GlobalArgs {
 17	        format: OutputFormat::Json,
 18	        cwd: root.to_path_buf(),
 19	        dry_run: false,
 20	    };
 21	
 22	    // 1. Enter pre-release mode with tag 'beta'
 23	    let enter_res = commands::pre::handle(
 24	        PreArgs::Enter {
 25	            tag: "beta".to_string(),
 26	        },
 27	        &global,
 28	    );
 29	    assert!(enter_res.is_ok());
 30	    assert!(root.join(".changeset/pre.json").exists());
 31	
 32	    // 2. Add changeset for minor bump
 33	    let add_res = commands::add::handle(
 34	        AddArgs {
 35	            packages: vec!["core-crate:minor".to_string()],
 36	            summary: Some("Beta feature".to_string()),
 37	        },
 38	        &global,
 39	    );
 40	    assert!(add_res.is_ok());
 41	
 42	    // 3. Version in pre-release mode -> should produce 0.2.0-beta.0
 43	    let version_res = commands::version::handle(
 44	        VersionArgs {
 45	            refresh_lockfiles: false,
 46	            no_refresh_lockfiles: true,
 47	            strict: false,
 48	            allow_empty_changesets: false,
 49	            emit_decision: None,
 50	        },
 51	        &global,
 52	    );
 53	    assert!(version_res.is_ok());
 54	
 55	    let updated_cargo = fs::read_to_string(root.join("crates/core/Cargo.toml")).unwrap();
 56	    assert!(updated_cargo.contains("0.2.0-beta.0"));
 57	
 58	    // 4. Exit pre-release mode
 59	    let exit_res = commands::pre::handle(PreArgs::Exit, &global);
 60	    assert!(exit_res.is_ok());
 61	
 62	    // 5. Final versioning after exit -> should finalize to 0.2.0
 63	    let final_version_res = commands::version::handle(
 64	        VersionArgs {
 65	            refresh_lockfiles: false,
 66	            no_refresh_lockfiles: true,
 67	            strict: false,
 68	            allow_empty_changesets: true,
 69	            emit_decision: None,
 70	        },
 71	        &global,
 72	    );
 73	    assert!(final_version_res.is_ok());
 74	
 75	    let final_cargo = fs::read_to_string(root.join("crates/core/Cargo.toml")).unwrap();
