340	/// Running `version` twice in pre mode with no new changeset must not duplicate the changelog entry.
341	#[test]
342	fn test_pre_mode_rerun_does_not_duplicate_changelog_entry() {
343	    let dir = setup_polyglot_git_repo();
344	    let root = dir.path();
345	
346	    let global = GlobalArgs {
347	        format: OutputFormat::Json,
348	        cwd: root.to_path_buf(),
349	        dry_run: false,
350	    };
351	
352	    commands::pre::handle(
353	        PreArgs::Enter {
354	            tag: "beta".to_string(),
355	        },
356	        &global,
357	    )
358	    .expect("pre enter must succeed");
359	
360	    commands::add::handle(
361	        AddArgs {
362	            packages: vec!["core-crate:minor".to_string()],
363	            summary: Some("Beta feature".to_string()),
364	        },
365	        &global,
366	    )
367	    .expect("add must succeed");
368	
369	    for _ in 0..2 {
370	        commands::version::handle(
371	            VersionArgs {
372	                refresh_lockfiles: false,
373	                no_refresh_lockfiles: true,
374	                strict: false,
375	                allow_empty_changesets: false,
376	                emit_decision: None,
377	            },
378	            &global,
379	        )
380	        .expect("version must succeed in pre mode");
381	    }
382	
383	    let pre_json = fs::read_to_string(root.join(".changeset/pre.json")).unwrap();
384	    let pre_state = callisto_model::format::parse_pre_json(&pre_json).unwrap();
385	    assert_eq!(
386	        pre_state.changesets.len(),
387	        1,
388	        "pre.json must record exactly one changeset id (the one `add` created), not zero and not \
389	         duplicated across two `version` runs; got: {:?}",
390	        pre_state.changesets
391	    );
392	
393	    let changelog = fs::read_to_string(root.join("crates/core/CHANGELOG.md")).unwrap();
394	    let occurrences = changelog.matches("Beta feature").count();
395	    assert_eq!(
396	        occurrences, 1,
397	        "the changeset's changelog line must appear exactly once even after two `version` runs \
398	         in pre mode, got {occurrences} occurrences in:\n{changelog}"
399	    );
400	
401	    // Counts total bullet entries, not just a substring match, so a second synthesized entry can't hide alongside it.
402	    let total_entries = changelog.lines().filter(|l| l.starts_with("- ")).count();
403	    assert_eq!(
404	        total_entries, 1,
405	        "the changelog must have exactly one entry after two `version` runs in pre mode with no \
406	         commit between them, got {total_entries} in:\n{changelog}"
407	    );
408	
409	    // The changeset file must remain on disk -- pre mode never deletes it until `pre exit`'s consuming run.
410	    let cs_dir = root.join(".changeset");
411	    let remaining_md: Vec<_> = fs::read_dir(&cs_dir)
412	        .unwrap()
413	        .filter_map(|e| e.ok())
414	        .filter(|e| e.path().extension().and_then(|s| s.to_str()) == Some("md"))
415	        .filter(|e| e.file_name() != "README.md")
416	        .collect();
417	    assert!(
418	        !remaining_md.is_empty(),
419	        "the pre-mode changeset file must remain on disk until `pre exit`"
420	    );
421	}
