781	        for (mode, args) in [("pre", &["pre", "exit"][..]), ("exit", &["pre", "enter", "beta"][..])] {
782	            let temp = workspace(false, ".changeset");
783	            let root = temp.path();
784	            let text = json!({"mode":mode,"tag":"alpha","initialVersions":{"py-lib":"1.2.3-alpha.beta"},"changesets":["recorded"]}).to_string();
785	            write(root, ".changeset/pre.json", &text);
786	            let output = callisto(root, args);
787	            assert!(!output.status.success());
788	            assert!(
789	                String::from_utf8_lossy(&output.stderr).contains("E114"),
790	                "{}",
791	                String::from_utf8_lossy(&output.stderr)
792	            );
793	            assert_eq!(fs::read_to_string(root.join(".changeset/pre.json")).unwrap(), text);
794	            assert_versions(root, "1.2.3", "1.0.0", "2.0.0");
795	        }
796	    }
