798	    #[test]
799	    fn resuming_a_python_cycle_preserves_its_native_baseline_and_recorded_changesets() {
800	        let temp = workspace(false, ".changeset");
801	        let root = temp.path();
802	        run(root, &["pre", "enter", "alpha"]);
803	        run(
804	            root,
805	            &["add", "--package", "py-lib:minor", "--summary", "Resumed Python cycle"],
806	        );
807	        version(root);
808	        assert_versions(root, "1.3.0a0", "1.0.0", "2.0.0");
809	        run(root, &["pre", "exit"]);
810	        let exited = pre_json(root, ".changeset");
811	        run(root, &["pre", "enter", "beta"]);
812	        let resumed = pre_json(root, ".changeset");
813	        assert_eq!(resumed["initialVersions"], exited["initialVersions"]);
814	        assert_eq!(resumed["changesets"], exited["changesets"]);
815	        assert_eq!(resumed["mode"], "pre");
816	        assert_eq!(resumed["tag"], "beta");
817	        version(root);
818	        version(root);
819	        assert_versions(root, "1.3.0b1", "1.0.0", "2.0.0");
820	        let changelog = fs::read_to_string(root.join("packages/python/CHANGELOG.md")).unwrap();
821	        assert_eq!(changelog.matches("Resumed Python cycle").count(), 1);
822	    }
823	}

