301	    seed_initialized_workspace(root);
302	
303	    // --- pre enter --dry-run --format json ---
304	    let enter_out = Command::new(env!("CARGO_BIN_EXE_callisto"))
305	        .args([
306	            "--format",
307	            "json",
308	            "--dry-run",
309	            "--cwd",
