330	    assert_eq!(enter_json["mode"], "pre", "mode should be \"pre\" for enter");
331	    assert_eq!(enter_json["tag"], "beta", "tag should echo the supplied tag");
332	    assert_eq!(
333	        enter_json["path"], ".changeset/pre.json",
334	        "path should be the relative pre.json path"
335	    );
