342	        },
343	        &global(root, false),
344	    )
345	    .expect("real pre enter should succeed");
346	
347	    // --- pre exit --dry-run --format json ---
348	    let exit_out = Command::new(env!("CARGO_BIN_EXE_callisto"))
349	        .args([
350	            "--format",
351	            "json",
352	            "--dry-run",
353	            "--cwd",
354	            root.to_str().unwrap(),
355	            "pre",
356	            "exit",
357	        ])
358	        .output()
359	        .expect("callisto binary should be invocable");
360	
361	    assert!(
362	        exit_out.status.success(),
363	        "pre exit --dry-run should exit 0; stderr: {}",
364	        String::from_utf8_lossy(&exit_out.stderr)
365	    );
366	
367	    let exit_text = String::from_utf8(exit_out.stdout).expect("stdout is UTF-8");
368	    let exit_json: serde_json::Value = serde_json::from_str(&exit_text).expect("dry-run output must be valid JSON");
369	
370	    assert_eq!(exit_json["schemaVersion"], 1, "schemaVersion should be 1");
371	    assert_eq!(exit_json["command"], "pre", "command should be \"pre\"");
372	    assert_eq!(exit_json["dryRun"], true, "dryRun should be true");
373	    assert_eq!(exit_json["mode"], "exit", "mode should be \"exit\" for exit");
374	    assert_eq!(exit_json["tag"], "beta", "tag should be the tag from pre.json");
375	    assert_eq!(
376	        exit_json["path"], ".changeset/pre.json",
377	        "path should be the relative pre.json path"
378	    );
