   3	//! Black-box durable-release acceptance tests.
   4	//!
   5	//! These tests intentionally drive the compiled `callisto` binary over a
   6	//! real Git repository. Registry and forge programs are replaced only at the
   7	//! process boundary, allowing the test to assert the observable release
   8	//! contract without coupling to graph-private prepared-operation types.
   9	
  10	#[path = "common/release_harness.rs"]
  11	mod release_harness;
  12	
  13	use std::fs;
  14	
  15	use release_harness::*;
  16	
  17	mod historical_version_authority {
  18	    use super::*;
  19	    use std::path::Path;
  20	
  21	    use callisto_model::{atomic::atomic_write, ApplyPermit, ReleaseDecisionV1};
  22	
  23	    struct ManifestRoster(Vec<callisto_model::Package>);
  24	
  25	    impl callisto_graph::DependencyResolver for ManifestRoster {
  26	        fn packages(&self) -> impl Iterator<Item = &callisto_model::Package> {
  27	            self.0.iter()
  28	        }
  29	
  30	        fn dependencies_of(&self, _: &callisto_model::PackageId) -> impl Iterator<Item = &callisto_model::DepEdge> {
  31	            std::iter::empty()
  32	        }
  33	
  34	        fn dependents_of(&self, _: &callisto_model::PackageId) -> impl Iterator<Item = &callisto_model::DepEdge> {
  35	            std::iter::empty()
  36	        }
  37	    }
  38	
  39	    fn write(root: &Path, path: &str, content: &str) {
  40	        let path = root.join(path);
  41	        fs::create_dir_all(path.parent().unwrap()).unwrap();
  42	        atomic_write(&path, content, &ApplyPermit::force_for_tests()).unwrap();
  43	    }
