    61	            if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
    62	                resolver_by_path.entry(root_manifest.clone()).or_default().bump = Some((idx, bump.to.clone()));
    63	            }
    64	        }
    65	    }
    66	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
    67	        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
    68	            resolver_by_path
    69	                .entry(root_manifest.clone())
    70	                .or_default()
    71	                .rewrite_indices
    72	                .push(idx);
    73	        }
    74	    }
