use std::process::ExitCode;

use callisto_graph::apply::{apply_version_plan, ApplyOptions, ApplyOutcome};
use callisto_graph::commands::VersionOptions;
use callisto_model::{ApplyPermit, DiagnosticSeverity};

use crate::cli::{GlobalArgs, OutputFormat, VersionArgs};
use crate::error::CliError;
use crate::output::{emit_line, emit_report};
use crate::render;
use crate::runner::CliCommandRunner;
use crate::workspace::{load_workspace, select_inference};

pub fn handle(args: VersionArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    if global.dry_run && args.emit_decision.is_some() {
        return Err(CliError::VersionEmitDecisionDryRun);
    }

    let runner = CliCommandRunner;
    let ws = load_workspace(global, &runner)?;

    let inference = select_inference();
    let opts = VersionOptions {
        strict: args.strict,
        allow_empty_changesets: args.allow_empty_changesets,
    };

    let plan = callisto_graph::commands::plan_version(&ws, &inference, &opts)?;

    // Refuses when disk already shows a bump HEAD lacks while release inputs or staged version state remain.
    callisto_graph::commands::check_partial_run(&ws)?;

    // Escalated diagnostics (e.g. --strict on "no pending changesets") must fail before anything is written.
    let has_errors = plan.diagnostics.iter().any(|d| d.severity == DiagnosticSeverity::Error);

    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run);

    // Derived before any write so an invalid plan fails early; written only after apply succeeds.
    let pending_decision = if !has_errors {
        match args.emit_decision.as_deref() {
            Some(path) => {
                let decision = callisto_graph::commands::derive_release_decision(&ws, &plan)?;
                // Workspace-root-relative, not cwd-relative, so `git add -A` and a later `--decision` `git show` agree.
                Some((ws.root.join(path), decision))
            }
            None => None,
        }
    } else {
        None
    };

    let apply_opts = ApplyOptions {
        refresh_lockfiles: !args.no_refresh_lockfiles,
        transient: false,
    };

    let outcome = if has_errors {
        ApplyOutcome::default()
    } else {
        match permit.as_ref() {
            Some(permit) => apply_version_plan(&ws.root, &plan, &runner, &apply_opts, permit)?,
            None => ApplyOutcome::default(),
        }
    };

    if let (Some((full_path, decision)), Some(permit)) = (pending_decision.as_ref(), permit.as_ref()) {
        let content = serde_json::to_string_pretty(decision).expect("release decision serializes") + "\n";
        callisto_model::atomic::atomic_write(full_path, &content, permit).map_err(|source| CliError::Io {
            source,
            path: Some(full_path.clone()),
        })?;
    }

    let report = plan.to_report(outcome.lockfile_refresh_results);

    if global.dry_run && global.format == OutputFormat::Text {
        emit_line("[DRY-RUN] Version Plan Calculated (no files modified):")?;
    }

    match global.format {
        OutputFormat::Json => emit_report(&mut std::io::stdout(), &report, global.dry_run)?,
        OutputFormat::Text => render::render_version(&report, &ws.config, &mut std::io::stdout())?,
    }

    // Mirrors the pattern in status.rs: diagnostics ride in the report so the
    // caller sees full detail before the non-zero exit.
    if has_errors {
        Ok(ExitCode::FAILURE)
    } else {
        Ok(ExitCode::SUCCESS)
    }
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use callisto_graph::commands::{plan_version, VersionOptions};
    use callisto_graph::infer::NoInference;
    use callisto_graph::locate::IgnoreWalkLocator;
    use callisto_graph::Workspace;
    use callisto_model::{CommandError, CommandOutput, CommandRunner, PackageId};

    struct NoopRunner;

    impl CommandRunner for NoopRunner {
        fn run(&self, _program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            Ok(CommandOutput {
                exit_code: Some(0),
                stdout: String::new(),
                stderr: String::new(),
            })
        }
    }

    fn git_init_with_commit(root: &Path) {
        callisto_fixtures::git::init_repo(root);
        std::fs::write(root.join(".gitkeep"), "").unwrap();
        for args in [vec!["add", "."], vec!["commit", "-q", "-m", "init"]] {
            std::process::Command::new("git")
                .args(&args)
                .current_dir(root)
                .output()
                .expect("git must be installed");
        }
    }

    fn run_git(root: &Path, args: &[&str]) {
        let status = std::process::Command::new("git")
            .args(args)
            .current_dir(root)
            .status()
            .expect("git must be installed");
        assert!(status.success(), "git {args:?} failed");
    }

    fn make_fixture(root: &Path) {
        git_init_with_commit(root);

        std::fs::create_dir_all(root.join("pkg-alpha")).unwrap();
        std::fs::write(
            root.join("pkg-alpha/Cargo.toml"),
            "[package]\nname = \"pkg-alpha\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();

        std::fs::create_dir_all(root.join(".changeset")).unwrap();
        std::fs::write(
            root.join(".changeset/bump-alpha.md"),
            "---\n\"pkg-alpha\": minor\n---\n\nAdd a new feature.\n",
        )
        .unwrap();
    }

    /// Spec: the text rendering of a `VersionReport` produced from a workspace
    /// with a pending changeset must include the package name and both the
    /// `from` and `to` version strings. The `render_version` function writes
    /// one line per bump in the format `<name> <from> → <to>`.
    #[test]
    fn version_text_output_includes_package_name_and_versions() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        make_fixture(root);

        let locator = IgnoreWalkLocator::new(root);
        let runner = NoopRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let inference = NoInference;
        let opts = VersionOptions {
            strict: false,
            allow_empty_changesets: true,
        };

        let plan = plan_version(&ws, &inference, &opts).expect("plan_version must succeed");
        let report = plan.to_report(None);

        // The report must include a bump for pkg-alpha.
        let pkg_alpha = PackageId::parse("pkg-alpha").unwrap();
        let bump = report
            .bumps
            .iter()
            .find(|b| b.package == pkg_alpha)
            .expect("pkg-alpha must have a planned bump");

        assert_eq!(bump.from.render(), "1.0.0", "from version must be the current version");
        assert_eq!(
            bump.to.render(),
            "1.1.0",
            "to version must be a minor bump (1.0.0 -> 1.1.0)"
        );

        // Render text output and verify it contains the key strings.
        let mut text_out = Vec::new();
        crate::render::render_version(&report, &ws.config, &mut text_out).unwrap();
        let rendered = String::from_utf8(text_out).unwrap();

        assert!(
            rendered.contains("pkg-alpha"),
            "text output must include package name; got:\n{rendered}"
        );
        assert!(
            rendered.contains("1.0.0"),
            "text output must include from version; got:\n{rendered}"
        );
        assert!(
            rendered.contains("1.1.0"),
            "text output must include to version; got:\n{rendered}"
        );
    }

    /// The empty-changeset diagnostic is deliberately
    /// governed by `validation.allow-empty-changesets` even when nobody set
    /// it, so an operator seeing the warning knows which key silences it.
    /// `render_version` must surface that as an attribution line, not just
    /// the bare diagnostic message.
    #[test]
    fn version_text_output_attributes_empty_changeset_diagnostic_to_its_config_key() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();

item.stdout:
        )
        .collect();

    // Must run before the git-staging loop below, so refreshed lockfiles are on disk to be staged.
    if opts.refresh_lockfiles {
        let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();

        if active_ecosystems.contains(&Ecosystem::Cargo) {
            refresh_results.push(run_lockfile_refresh(
                runner,
                root,
                "Cargo.lock",
                "cargo",
                &["update", "--workspace"],
            )?);
        }

        if active_ecosystems.contains(&Ecosystem::Pypi) {
            if root.join("uv.lock").exists() {
                refresh_results.push(run_lockfile_refresh(runner, root, "uv.lock", "uv", &["lock"])?);
            } else if root.join("poetry.lock").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "poetry.lock",
                    "poetry",
                    &["lock", "--no-update"],
                )?);
            } else if root.join("pdm.lock").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "pdm.lock",
                    "pdm",
                    &["lock", "--update-reuse"],
                )?);
            }
        }

        if active_ecosystems.contains(&Ecosystem::Npm) {
            if root.join("package-lock.json").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "package-lock.json",
                    "npm",
                    &["install", "--package-lock-only", "--ignore-scripts"],
                )?);
            }
            if root.join("pnpm-lock.yaml").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "pnpm-lock.yaml",
                    "pnpm",
                    &["install", "--lockfile-only"],
                )?);
            }
            if root.join("yarn.lock").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "yarn.lock",
                    "yarn",
                    &["install", "--mode", "update-lockfile"],
                )?);
            }
            if root.join("bun.lock").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "bun.lock",
                    "bun",
                    &["install", "--lockfile-only"],
                )?);
            } else if root.join("bun.lockb").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "bun.lockb",
                    "bun",
                    &["install", "--lockfile-only"],
                )?);
            }
        }

        if !refresh_results.is_empty() {
            outcome.lockfile_refresh_results = Some(refresh_results);
        }
    }

    // Map each well-known lockfile to its ecosystem, then include the file
    // only when that ecosystem is active and the file exists on disk.
    let lockfile_ecosystems: &[(&str, Ecosystem)] = &[
        ("Cargo.lock", Ecosystem::Cargo),
        ("package-lock.json", Ecosystem::Npm),
        ("pnpm-lock.yaml", Ecosystem::Npm),
        ("yarn.lock", Ecosystem::Npm),
        ("bun.lock", Ecosystem::Npm),
        ("bun.lockb", Ecosystem::Npm),
        ("uv.lock", Ecosystem::Pypi),
        ("poetry.lock", Ecosystem::Pypi),
        ("pdm.lock", Ecosystem::Pypi),
        ("Pipfile.lock", Ecosystem::Pypi),
    ];
    for (lockfile, ecosystem) in lockfile_ecosystems {
        if !active_ecosystems.contains(ecosystem) {
            continue;
        }
        let p = PathBuf::from(lockfile);
        if root.join(&p).exists() && !modified_paths.contains(&p) {
            modified_paths.push(p);
        }
    }

    if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
        // Stage all written release state before consuming its inputs. If a refresh or add fails,
        // the changesets/pre-state remain available; if removal staging fails, the manifest diff
        // still identifies the interrupted run.
        let (existing, deleted): (Vec<_>, Vec<_>) = modified_paths.iter().partition(|p| root.join(p).exists());

        if !existing.is_empty() {
            let mut args = vec!["add", "--"];
            let strs: Vec<String> = existing.iter().map(|p| p.display().to_string()).collect();
            for s in &strs {
                args.push(s);
            }
            let output = runner.run("git", &args, root)?;
            if !output.success() {
                return Err(GraphError::Command(CommandError::Failed {
                    program: "git".to_string(),
                    exit_code: output.exit_code,
                    stderr: output.redacted_stderr(),
                }));
            }
        }

        if !deleted.is_empty() {
            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
            let strs: Vec<String> = deleted.iter().map(|p| p.display().to_string()).collect();
            for s in &strs {
                args.push(s);
            }
            let output = runner.run("git", &args, root)?;
            if !output.success() {
                return Err(GraphError::Command(CommandError::Failed {
                    program: "git".to_string(),
                    exit_code: output.exit_code,
                    stderr: output.redacted_stderr(),
                }));
            }
        }

        if !deferred_deletions.is_empty() {
            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
            let strs: Vec<String> = deferred_deletions.iter().map(|p| p.display().to_string()).collect();
            for s in &strs {
                args.push(s);
            }
            let output = runner.run("git", &args, root)?;
            if !output.success() {
                return Err(GraphError::Command(CommandError::Failed {
                    program: "git".to_string(),
                    exit_code: output.exit_code,
                    stderr: output.redacted_stderr(),
                }));
            }

            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
            for path in &deferred_deletions {
                let full = root.join(path);
                if full.exists() {
                    fs::remove_file(&full).map_err(|e| GraphError::ApplyIo {
                        path: path.clone(),
                        message: e.to_string(),
                    })?;
                }
            }
            modified_paths.extend(deferred_deletions.iter().cloned());
        }

        outcome.staged = modified_paths;
    }

    Ok(outcome)
}

