    #[diagnostic(
        code(E197),
        help("Configure one supported product package and its artifact targets.")
    )]
    InvalidProductRelease { detail: String },

    #[error(transparent)]
    #[diagnostic(transparent)]
    Tag(#[from] TagTemplateError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    VersionParse(#[from] VersionParseError),
}

